"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[522],{91322:function(e,n,t){t.d(n,{T:function(){return i}});let i={"bengal-unlearning":[{kind:"site",label:{en:"SHRED project site",cn:"SHRED 项目网站"},href:"https://zizhao-hu.github.io/bengal-unlearning/",note:{en:"Method, results and figures.",cn:"方法、结果与图表。"},embed:!0},{kind:"slides",label:"SHRED: Retain-Set-Free Unlearning via Self-Distillation with Logit Demotion",href:"/projects/shred/shred-talk.html",note:{en:"Paper talk.",cn:"论文报告。"},embed:!0},{kind:"slides",label:"From Continual Learning to Unlearning",href:"/projects/shred/continual-to-unlearning.html",note:{en:"Background talk framing unlearning against continual learning.",cn:"从持续学习的角度讲解反学习的背景报告。"},embed:!0},{kind:"paper",label:"arXiv:2605.07482",href:"https://arxiv.org/abs/2605.07482",note:{en:"NeurIPS 2026.",cn:"NeurIPS 2026。"}},{kind:"code",label:"github.com/zizhao-hu/bengal-unlearning",href:"https://github.com/zizhao-hu/bengal-unlearning"}],"context-is-the-new-weight":[{kind:"site",label:{en:"Project site",cn:"项目网站"},href:"https://zizhao-hu.github.io/context-is-the-new-weight/",embed:!0},{kind:"slides",label:"Context Is the New Weight",href:"/presentations/context-is-the-new-weight/index.html",embed:!0},{kind:"code",label:"github.com/zizhao-hu/context-is-the-new-weight",href:"https://github.com/zizhao-hu/context-is-the-new-weight"}],"multiagent-emotion-steering":[{kind:"slides",label:"Multi-agent Emotion Steering",href:"/presentations/multiagent-emotion-steering/index.html",embed:!0},{kind:"code",label:"github.com/zizhao-hu/multiagent-emotion-steering",href:"https://github.com/zizhao-hu/multiagent-emotion-steering"}],"md.md":[{kind:"code",label:"github.com/zizhao-hu/md.md",href:"https://github.com/zizhao-hu/md.md"}]}},54691:function(e,n,t){t.d(n,{F:function(){return i}});let i=[{name:"Bengal \xb7 SHRED",slug:"bengal-unlearning",desc:{en:"Retain-set-free LLM unlearning, developed under the IARPA Bengal program. Demotes memorized logits at high-surprisal tokens via self-distillation, with no curated retain set required.",cn:"无需保留集的大模型反学习，在美国政府 IARPA Bengal 项目下研发。通过自蒸馏抑制高信息量 token 上被记住的 logit，不需要人工构造保留集。"}},{name:"Context Is the New Weight",slug:"context-is-the-new-weight",desc:{en:"In-context memory and adaptation for LLM agents.",cn:"面向大模型智能体的上下文记忆与自适应。"}},{name:"Multi-agent Emotion Steering",slug:"multiagent-emotion-steering",desc:{en:"Persona and emotion vectors as intrinsic reward for multi-agent LLM cooperation: contagion and cause attribution on GSM8K.",cn:"将人格／情绪向量作为多智能体协作的内在奖励，在 GSM8K 上研究情绪传染与归因。"}},{name:"md.md",slug:"md.md",desc:{en:"A meta markdown file that evolves on its own.",cn:"一个能自我演化的元 markdown 文件。"}},{name:"Meta-Markdown Memory",slug:"meta-markdown-memory",private:!0},{name:"Human Input Variations",slug:"human-input-variations",private:!0},{name:"Human Input Variations \xb7 paper",slug:"human-input-variations-paper",private:!0},{name:"Multi-turn Correction",slug:"multiturn-correction",private:!0},{name:"Weight Tying",slug:"weighttying",private:!0},{name:"GLAMOR Onboarding \xb7 paper",slug:"glamor-research-onboarding-paper",private:!0},{name:"Jinshidian 金石典",slug:"jinshidian",private:!0},{name:"Obsidian Vault",slug:"obsidian-vault",private:!0},{name:"Personal Site",slug:"personal-site",private:!0}]},42299:function(e,n,t){t.d(n,{IQ:function(){return m},Li:function(){return c}});var i=t(64972),a=t(95805),o=t(71947),r=t(72613),s=t(80754),l=t(88906),d=t(82023),h=t(91322);let g=[{title:"Context Is the New Weight",slug:"context-is-the-new-weight",description:"In-context memory and adaptation for LLM agents — treating the context window as the store that carries what the model knows about the task at hand, rather than the weights.",details:[],tags:["Agentic Memory","In-context Learning","LLM"],status:"research",icon:i.Z,color:"cyan",deliverables:h.T["context-is-the-new-weight"]},{title:"Multi-agent Emotion Steering",slug:"multiagent-emotion-steering",description:"Persona and emotion vectors as intrinsic reward for multi-agent LLM cooperation — measuring contagion between agents and cause-attribution on GSM8K.",details:[],tags:["Multi-agent","Steering","LLM"],status:"research",icon:a.Z,color:"amber",deliverables:h.T["multiagent-emotion-steering"]},{title:"md.md",slug:"md.md",description:"A meta markdown file that evolves on its own.",details:[],tags:["Experiment"],status:"prototype",icon:o.Z,color:"violet",deliverables:h.T["md.md"]},{title:"Bengal: Retain-Set-Free Unlearning (SHRED)",slug:"bengal-unlearning",description:"SHRED (Self-distillation via High-surprisal-only Retain-set-free Entropy Demotion) is an LLM unlearning method developed under the U.S. government IARPA Bengal program. Most unlearning methods need a curated retain set to keep general utility from collapsing; SHRED needs only the forget set. Within each forget instance it treats the highest-information tokens as what actually carries the memorized knowledge, and leaves the rest as benign anchors.",details:["Developed under the IARPA Bengal program — removing memorized private, copyrighted, or hazardous content from pretrained LLMs","Retain-set-free: drops the curated-retain-set dependency that most unlearning methods carry","Selection — per-token autoregressive probabilities pick the lowest-probability (highest Shannon information) positions as forget targets; the rest stay as benign anchors","Training — one top-k KL self-distillation objective demotes the memorized token's logit at forget positions while preserving the original distribution at benign ones","New Pareto-optimal forget-efficacy/utility trade-off across four unlearning benchmarks, beating retain-set-dependent methods","Robust to relearning and membership-inference attacks; utility stays stable across many sequential unlearning runs","Accepted at NeurIPS 2026 \xb7 PI: Robin Jia \xb7 Co-PI: Jesse Thomason"],tags:["Unlearning","LLM","AI Safety","Self-Distillation","Research"],status:"research",icon:r.Z,color:"blue",link:"https://zizhao-hu.github.io/bengal-unlearning/",github:"https://github.com/zizhao-hu/bengal-unlearning",deliverables:h.T["bengal-unlearning"],content:"\n# Bengal: Retain-Set-Free Unlearning (SHRED)\n\n**SHRED** — *Self-distillation via High-surprisal-only Retain-set-free Entropy Demotion* — is an LLM unlearning method developed under the U.S. government **IARPA Bengal** program. The goal: remove memorized content such as private data, copyrighted text, or hazardous knowledge from a pretrained model, without costly full retraining and without degrading unrelated capabilities.\n\n## The Problem\n\nMost unlearning methods need a **retain set** — curated examples of what the model should still know — to stop general utility collapsing while it forgets. That is an extra data dependency, and it complicates deployment: you have to source and maintain a retain corpus alongside every forget request.\n\n## The Insight\n\nNot all tokens inside a forget-set instance carry memorized information equally. **High-information tokens** — the ones the model finds surprising, with low autoregressive probability — concentrate the memorized knowledge. **Low-information tokens** reflect general language competence and are worth protecting. So the forget set already contains its own anchors; a separate retain set is not required.\n\n## The Method\n\nTwo stages, using only the forget set:\n\n1. **Selection.** A forward pass over a forget instance collects per-token autoregressive probabilities. The lowest-probability tokens — highest Shannon information — become the *forget positions*; the remaining positions are kept as *benign anchors*.\n2. **Training.** Modified KL targets demote the memorized token's logit at the forget positions while preserving the original distribution at the benign ones. A single top-k KL self-distillation objective then drives forgetting and utility preservation at the same time.\n\n## Evaluation\n\nAcross four standard unlearning benchmarks, SHRED sets a new Pareto-optimal trade-off between forget efficacy and model utility, outperforming retain-set-dependent methods. It holds up against relearning attacks and membership-inference attacks, and utility stays stable across many sequential unlearning runs.\n\n## Status\n\nAccepted at **NeurIPS 2026**. PI: Dr. Robin Jia \xb7 Co-PI: Dr. Jesse Thomason.\n"},{title:"Physics-Based AI Image Detection",slug:"physics-ai-detection",description:"Detecting AI-generated images through physics-based reasoning — analyzing depth maps, brightness-depth consistency, and light estimation to expose how AI fails to model real-world physics. A 3-feature classifier achieves 68.3% accuracy with just depth gradients and brightness edge analysis.",details:["Key finding: AI images are paradoxically too physically consistent — overly smooth brightness-depth relationships and symmetric depth distributions","Yet AI images show sharper depth gradients (d=0.653), revealing lack of true 3D understanding","3-feature model (grad_mean, brightness_at_depth_edges, n_valid_patches) outperforms full 27-feature model by 13.3pp","27 physics features across depth statistics, brightness-depth coupling, and light estimation pipelines","PCA reveals real/fake signal is not dominant — scene complexity dominates, requiring targeted feature selection"],tags:["Computer Vision","AI Detection","Physics-Based","Depth Estimation","Research"],status:"active",icon:s.Z,color:"rose",github:"https://github.com/zizhao-hu/vlmdraw",image:"/images/projects/vlmdraw-depth.png",content:"\n# Physics-Based AI Image Detection\n\nCan you detect AI-generated images by checking if they obey the laws of physics? That's the core question behind this project.\n\n## The Insight\n\nAI image generators (DALL-E, Midjourney, Stable Diffusion) produce visually stunning images — but they don't actually understand physics. They approximate what scenes *look like* without modeling how light, depth, and surface interactions *actually work*.\n\nThis project exploits that gap.\n\n## Three Physics Pipelines\n\nWe extract 27 features from three complementary physics-based analysis pipelines, applied to 30 real images (COCO) and 30 AI-generated images (AIGenBench):\n\n### 1. Depth Map Statistics\nUsing monocular depth estimation, we analyze the statistical properties of predicted depth maps:\n- **gradient mean/std** — how sharply depth transitions occur\n- **skewness/kurtosis** — asymmetry and tail behavior of depth distributions\n- **entropy** — information content of the depth field\n\n### 2. Brightness-Depth Consistency\nIn real photographs, brightness and depth are physically coupled — objects farther away tend to have different illumination characteristics. We measure:\n- **Pearson/Spearman correlation** between brightness and depth\n- **Local patch correlations** — spatial consistency of the brightness-depth relationship\n- **Brightness at depth edges** — what happens to brightness where depth changes sharply\n\n### 3. Light Estimation\nReal scenes have consistent lighting from a single dominant source. AI-generated images often have subtle inconsistencies:\n- **Global residual** — how well a single light model fits the scene\n- **Angular deviation** — variance in estimated light direction across patches\n- **Fraction anomalous patches** — percentage of regions with inconsistent lighting\n\n## Key Findings\n\n### The Paradox of AI Images\n\n![Depth Map Statistics: Real vs. AI-Generated](/images/projects/vlmdraw-depth.png)\n\n**AI-generated images are simultaneously too consistent AND too sharp:**\n\n| Finding | What It Means |\n|---------|--------------|\n| **Smooth brightness-depth** | AI produces overly uniform brightness-depth relationships (d=0.445) |\n| **Symmetric depth distributions** | Real images have skewed depth (0.556 vs 0.236) — AI makes everything too balanced |\n| **More uniform lighting** | Fewer anomalous patches in AI images (41% vs 51%) |\n| **But sharper depth gradients** | AI images have abrupt depth transitions (d=0.653) — the strongest signal |\n\nThe last finding is the most interesting: **AI generators create sharp, almost cartoon-like depth boundaries** because they haven't learned that real-world depth transitions are gradual (due to actual 3D geometry, not learned textures).\n\n### Feature Ranking by Effect Size\n\nThe top discriminative features ranked by Cohen's d:\n\n| Rank | Feature | Cohen's d | Direction |\n|------|---------|-----------|-----------|\n| 1 | Depth gradient mean | **0.653** | Fake > Real |\n| 2 | Brightness at depth edges | **0.547** | Real > Fake |\n| 3 | Local correlation (abs mean) | 0.445 | Fake > Real |\n| 4 | Fraction strong correlation | 0.428 | Fake > Real |\n| 5 | Gradient magnitude correlation | 0.376 | Fake > Real |\n| 6 | Depth skewness | 0.356 | Real > Fake |\n| 7 | Fraction anomalous patches | 0.307 | Real > Fake |\n\n### Less Is More: The Classifier\n\n![Brightness-Depth Features: Real vs. AI-Generated](/images/projects/vlmdraw-brightness.png)\n\nWe trained logistic regression classifiers with leave-one-out cross-validation:\n\n| Model | Accuracy | F1 | Train Acc | Gap |\n|-------|----------|-----|-----------|-----|\n| All 27 features | 55.0% | 0.542 | 81.7% | 26.7pp |\n| **3 features** | **68.3%** | **0.678** | 71.7% | **3.4pp** |\n\nThe 3-feature model uses only **grad_mean**, **brightness_at_depth_edges**, and **n_valid_patches** — and generalizes far better because:\n- 27 features overfit on 60 samples\n- The top features capture complementary physics violations\n- Minimal train/test gap (3.4pp) indicates genuine signal, not memorization\n\n### The Decision Rule\n\nClassify as **FAKE** if:\n\n```\n1.43 \xd7 z(grad_mean) − 1.26 \xd7 z(brightness_at_depth_edges) + 0.04 > 0\n```\n\nTranslation: an image is likely AI-generated if it has **sharp depth gradients** (doesn't understand 3D geometry) combined with **low brightness variation at depth edges** (doesn't understand light-surface interaction).\n\n### PCA Analysis\n\n![Light Estimation Features: Real vs. AI-Generated](/images/projects/vlmdraw-light.png)\n\n27 features compress into 6 principal components capturing ~77% of variance:\n\n| PC | Variance | Interpretation |\n|----|----------|----------------|\n| PC1 | 24.1% | Scene complexity (entropy, skewness, kurtosis) |\n| PC2 | 15.3% | Lighting quality (angular deviation, anomalous patches) |\n| PC3 | 13.8% | Brightness-depth coupling (pearson_r, spearman_r) |\n| PC4 | 10.6% | Depth distribution shape (std, iqr, grad_mean) |\n| PC5 | 7.5% | Information content (mutual_information) |\n\n**Critical insight**: The real/fake signal is NOT the dominant axis of variation. Scene-level variation (complexity, depth range) dominates, which is why targeted feature selection outperforms using all features.\n\n## Limitations & Future Work\n\n- **Sample size**: 30 images per class is a proof-of-concept — scaling to thousands would strengthen results\n- **Generator diversity**: Tested on AIGenBench; extending to DALL-E 3, Midjourney v6, Flux would test generalizability\n- **Depth estimator dependency**: Results depend on the quality of the monocular depth model\n- **Complementary approaches**: Physics features could be combined with frequency-domain or learned detectors for higher accuracy\n\n## Conclusion\n\nThis project demonstrates that **physics-based reasoning can detect AI-generated images** without any training on specific generators. The key insight — AI images are paradoxically too consistent while having unnaturally sharp depth transitions — reveals a fundamental limitation of current image generators: they learn to approximate visual appearance without genuinely understanding the physical world that produces those appearances.\n"},{title:"DREAM-C2L: Continual Learning Framework",slug:"dream-c2l",description:"Open-source framework for continual learning research. Enabling AI systems to learn continuously without catastrophic forgetting, adapting to new data while preserving prior knowledge.",details:["Difficulty-aware sample ordering algorithms","Replay-based and regularization methods for knowledge retention","Reproducible experiment pipelines for HPC clusters","Integration with PyTorch Lightning and Weights & Biases"],tags:["Continual Learning","PyTorch","Open Source","Research"],status:"active",icon:i.Z,color:"green",github:"https://github.com/zizhao-hu/dream-c2l",image:"/images/projects/dream.png",content:"\n# DREAM-C2L: Continual Learning Framework\n\nAn open-source framework for continual learning research, designed for reproducibility and scalability on HPC clusters.\n\n## What Is Continual Learning?\n\nTraditional neural networks suffer from **catastrophic forgetting** — when trained on new data, they lose performance on previously learned tasks. Continual learning aims to solve this: how can a model learn new things without forgetting old ones?\n\n## The DREAM Framework\n\nDREAM-C2L (Difficulty-aware REplay And Memory for Curriculum-to-Lifelong learning) introduces a principled approach to ordering and replaying training samples.\n\n### Core Ideas\n\n- **Curriculum-aware sample ordering**: Instead of random shuffling, order training examples by difficulty. Easy samples first builds a strong foundation; hard samples later refine decision boundaries.\n- **Replay buffer management**: Maintain a balanced memory of past experiences, selected to maximize coverage of the learned distribution.\n- **Regularization**: Constrain how much model weights can change when learning new tasks, preventing catastrophic forgetting.\n\n### Key Features\n\n- **Modular pipeline**: Swap replay strategies, regularization methods, and difficulty metrics independently\n- **HPC-ready**: Built-in SLURM job management, multi-GPU training, checkpointing\n- **Reproducible**: Full experiment tracking with Weights & Biases integration\n- **PyTorch Lightning backbone**: Clean training loops with automatic mixed precision\n\n## Research Applications\n\nThe framework supports multiple continual learning scenarios:\n- **Class-incremental**: New classes appear over time\n- **Task-incremental**: New tasks with explicit boundaries\n- **Domain-incremental**: Same task, shifting data distributions\n\n## Results\n\nOur difficulty-aware approach shows consistent improvements over random ordering baselines across CIFAR-100, TinyImageNet, and ImageNet-subset benchmarks.\n\nThe key insight: **the order in which a model sees data matters as much as what data it sees**. By presenting examples in a curriculum-informed order, the model builds more robust internal representations that resist forgetting.\n"},{title:"Project Canary",slug:"project-canary",description:"Foundational MOVE Fellowship project (Sept-Oct 2025) — a community-driven effort to train and refine frontier AI models. Completed 15,000+ tasks across 15 domains, improving Review 1 approval rates from 10% to 40%.",details:["High-volume task generation across CS, Math, Medicine, Physics domains","Core contributor in Computer Science domain","Quality improvement: raised approval rates from 10% to 40%","Precursor to Project Orion's specialized refinement phase"],tags:["AI Training","Data Generation","Handshake AI","MOVE Fellowship"],status:"completed",icon:l.Z,color:"green",content:"\n# Project Canary — MOVE Fellowship Foundation\n\nThe foundational phase of the MOVE Fellowship at Handshake AI (Sept–Oct 2025), focused on large-scale task generation to train and refine frontier AI models.\n\n## Overview\n\nProject Canary was a community-driven initiative where subject-matter experts contributed training tasks across 15 academic domains. The goal: generate high-quality, diverse training data that would push frontier models toward deeper domain expertise.\n\n## My Contribution\n\nAs a **core contributor in the Computer Science domain**, I:\n- Generated and reviewed tasks covering algorithms, data structures, systems design, machine learning, and software engineering\n- Contributed to over **15,000 tasks** across the fellowship\n- Focused on tasks requiring PhD-level reasoning — problems that couldn't be solved by simply retrieving information\n\n## Impact\n\n### Quality Metrics\nThe most significant achievement was improving task quality:\n\n| Metric | Before | After |\n|--------|--------|-------|\n| Review 1 approval rate | **10%** | **40%** |\n| Tasks completed | — | 15,000+ |\n| Domains covered | — | 15 |\n\nA 4\xd7 improvement in first-review approval rates meant significantly less rework, faster iteration, and higher-quality training data reaching the model.\n\n### Lessons Learned\n\n1. **Domain expertise matters**: Generic annotators produce generic data. PhD-level contributors produce training signal that actually moves the needle on hard problems.\n2. **Quality over quantity**: A single well-crafted reasoning task is worth more than a hundred trivial ones.\n3. **Review feedback loops**: Tight review cycles with specific feedback accelerate quality improvement dramatically.\n\n## Legacy\n\nProject Canary laid the groundwork for **Project Orion** — the specialized refinement phase that followed, where the broad data generation shifted to targeted reasoning, safety, and red-teaming work.\n"},{title:"Project Orion",slug:"project-orion",description:"Advanced MOVE Fellowship phase (Nov 2025) — specialized refinement of frontier AI models. Focused on high-quality reasoning chains, safety injections, and red-teaming through jailbreak testing. One-month intensive following Project Canary.",details:["High-quality reasoning refinement and chain-of-thought improvement","Safety injection tasks: embedding guardrails into model behavior","Red-teaming and jailbreak testing for frontier models","Built on Canary foundations with deeper specialization in CS domain"],tags:["AI Safety","Reasoning","Red-Teaming","Handshake AI","MOVE Fellowship"],status:"completed",icon:d.Z,color:"orange",content:'\n# Project Orion — Advanced Model Refinement\n\nThe advanced phase of the MOVE Fellowship at Handshake AI (Nov 2025), shifting from broad data generation to specialized model refinement.\n\n## From Canary to Orion\n\nWhile Project Canary focused on volume and coverage across 15 domains, **Project Orion** narrowed the focus to three critical areas:\n\n1. **Reasoning refinement** — improving how models think through complex problems\n2. **Safety injections** — embedding guardrails directly into model behavior\n3. **Red-teaming** — finding and addressing vulnerabilities through jailbreak testing\n\n## Reasoning Refinement\n\n### Chain-of-Thought Improvement\nNot just getting the right answer, but ensuring the model\'s *reasoning process* is sound:\n- Identifying cases where models reach correct answers through flawed logic\n- Rewiring reasoning chains to be logically sound, step-by-step\n- Creating training examples that demonstrate expert-level problem decomposition\n\n### Quality Over Previous Phase\nWhere Canary tasks tested "can you solve this?", Orion tasks tested "can you solve this *correctly, for the right reasons, showing your work*?"\n\n## Safety Injections\n\n### Embedding Guardrails\nSafety isn\'t a filter bolted on after training — it needs to be woven into the model\'s core behavior:\n- Creating scenarios where the model must recognize and refuse harmful requests\n- Building training data for graceful refusals that explain *why* something is problematic\n- Edge cases: requests that seem benign but could enable harm\n\n### The Subtlety Problem\nThe hardest cases aren\'t obvious "how do I build a bomb" requests. They\'re:\n- Multi-step requests where each step seems innocent\n- Context-dependent requests that require judgment\n- Dual-use knowledge that has both legitimate and harmful applications\n\n## Red-Teaming & Jailbreak Testing\n\n### Finding Vulnerabilities\nSystematically probing the model for failure modes:\n- **Prompt injection**: Embedding instructions that override system prompts\n- **Role-play attacks**: Getting models to "play a character" that bypasses safety\n- **Encoding tricks**: Using base64, rot13, or other encodings to sneak past filters\n- **Multi-turn manipulation**: Slowly escalating across a conversation\n\n### Why This Matters\nEvery vulnerability found in testing is one that won\'t be exploited in production. Red-teaming is the immune system of AI safety.\n\n## Impact\n\nBuilding on Canary\'s foundation, Orion produced targeted, high-impact training data that directly improved model reasoning quality and safety behavior. The one-month intensive demonstrated that focused expert refinement can achieve more than months of broad data generation.\n'}],c={"Agentic Memory":"智能体记忆","In-context Learning":"上下文学习",LLM:"大模型","Multi-agent":"多智能体",Steering:"引导",Experiment:"实验",Unlearning:"反学习","AI Safety":"AI 安全","Self-Distillation":"自蒸馏",Research:"研究","Computer Vision":"计算机视觉","AI Detection":"AI 检测","Physics-Based":"基于物理","Depth Estimation":"深度估计","Continual Learning":"持续学习","Open Source":"开源","AI Training":"AI 训练","Data Generation":"数据生成",Reasoning:"推理","Red-Teaming":"红队测试"};function m(e){return g.find(n=>n.slug===e)}}}]);